@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

<http://www.example.org/ontology#EDIFACT-INVOIC-Ontology> a owl:Ontology ;
    rdfs:label "EDIFACT INVOIC Profound Ontology" ;
    rdfs:comment "A comprehensive OWL2 ontology for the structure of EDIFACT D96A INVOIC messages, supporting EN 16931-1, P2P-O alignment, and SHACL validation." .

#################################################################
# CORE CLASSES
#################################################################

:InterchangeEnvelope a owl:Class ;
    rdfs:label "Interchange Envelope" ;
    rdfs:comment "The top-level UN/EDIFACT envelope containing one or more messages." .

:Message a owl:Class ;
    rdfs:label "Message" ;
    rdfs:comment "A business message such as INVOIC within the Interchange Envelope." .

:Segment a owl:Class ;
    rdfs:label "Segment" ;
    rdfs:comment "A generic EDIFACT segment, the building block of a message." .

:CompositeDataElement a owl:Class ;
    rdfs:label "Composite Data Element" ;
    rdfs:comment "A composite data element within a segment." ;
    rdfs:subClassOf :Segment .

:SimpleDataElement a owl:Class ;
    rdfs:label "Simple Data Element" ;
    rdfs:comment "A simple data element within a composite or segment." ;
    rdfs:subClassOf :Segment .

:Invoice a owl:Class ;
    rdfs:label "Invoice" ;
    rdfs:comment "An invoice document, represented as an INVOIC message." ;
    rdfs:subClassOf :Message .

:Organization a owl:Class ;
    rdfs:label "Organization" ;
    rdfs:comment "A business entity involved in the invoice (buyer, seller, delivery party, etc.)." .

:AgentRole a owl:Class ;
    rdfs:label "Agent Role" ;
    rdfs:comment "A specific role played by an organization in the context of an invoice (e.g., Buyer, Supplier, Delivery Party)." .
    owl:disjointWith :Organization .

:Address a owl:Class ;
    rdfs:label "Address" ;
    rdfs:comment "A postal or physical address related to an organization." .

:Identifier a owl:Class ;
    rdfs:label "Identifier" ;
    rdfs:comment "A generic identifier such as a Global Location Number." .

:GlobalLocationNumber a owl:Class ;
    rdfs:label "Global Location Number" ;
    rdfs:comment "A unique identifier for an organization location, e.g., GLN." ;
    rdfs:subClassOf :Identifier .

:Item a owl:Class ;
    rdfs:label "Item" ;
    rdfs:comment "A product or service listed in the invoice." .

:Price a owl:Class ;
    rdfs:label "Price" ;
    rdfs:comment "A price value associated with an item or invoice." .

:Quantity a owl:Class ;
    rdfs:label "Quantity" ;
    rdfs:comment "A quantity value for an item or invoice." .

:Tax a owl:Class ;
    rdfs:label "Tax" ;
    rdfs:comment "A tax concept applied to an item or invoice." .

:BusinessProcess a owl:Class ;
    rdfs:label "Business Process" ;
    rdfs:comment "A business process to which the invoice can be assigned." .

#################################################################
# SEGMENT-LEVEL AND PIVOT CLASSES
#################################################################

:BeginningOfMessage a owl:Class ;
    rdfs:label "Beginning of Message Segment (BGM)" ;
    rdfs:comment "The BGM segment, identifying the type and number of the document." ;
    rdfs:subClassOf :Segment .

:DateTimePeriod a owl:Class ;
    rdfs:label "Date/Time/Period Segment (DTM)" ;
    rdfs:comment "A DTM segment specifying a relevant date or period (e.g., invoice date, delivery date)." ;
    rdfs:subClassOf :Segment .

:Reference a owl:Class ;
    rdfs:label "Reference Segment (RFF)" ;
    rdfs:comment "A reference segment for document numbers, order references, etc." ;
    rdfs:subClassOf :Segment .

:PriceSegment a owl:Class ;
    rdfs:label "Price Segment (PRI)" ;
    rdfs:comment "A PRI segment specifying price details for line items." ;
    rdfs:subClassOf :Segment .

:QuantitySegment a owl:Class ;
    rdfs:label "Quantity Segment (QTY)" ;
    rdfs:comment "A QTY segment specifying quantity details for line items." ;
    rdfs:subClassOf :Segment .

:TaxSegment a owl:Class ;
    rdfs:label "Tax Segment (TAX)" ;
    rdfs:comment "A TAX segment specifying tax details for invoice or line items." ;
    rdfs:subClassOf :Segment .

:AllowanceChargeSegment a owl:Class ;
    rdfs:label "Allowance/Charge Segment (ALC)" ;
    rdfs:comment "An ALC segment specifying allowances or charges." ;
    rdfs:subClassOf :Segment .

:SectionControl a owl:Class ;
    rdfs:label "Section Control Segment (UNS)" ;
    rdfs:comment "A UNS segment marking section boundaries in the message." ;
    rdfs:subClassOf :Segment .

:MonetaryAmountSegment a owl:Class ;
    rdfs:label "Monetary Amount Segment (MOA)" ;
    rdfs:comment "A MOA segment with a specific qualifier (e.g. MOA+79, MOA+86, MOA+125, MOA+176, MOA+289)." ;
    rdfs:subClassOf :Segment .

:MeasurementSegment a owl:Class ;
    rdfs:label "Measurement Segment (MEA)" ;
    rdfs:comment "A MEA segment specifying measurements (e.g., weight, volume)." ;
    rdfs:subClassOf :Segment .

:PackagingSegment a owl:Class ;
    rdfs:label "Packaging Segment (PAC)" ;
    rdfs:comment "A PAC segment specifying packaging details." ;
    rdfs:subClassOf :Segment .

:TransportSegment a owl:Class ;
    rdfs:label "Transport Segment (TOD)" ;
    rdfs:comment "A TOD segment specifying transport arrangements." ;
    rdfs:subClassOf :Segment .

#################################################################
# REIFICATION/PIVOT CLASSES
#################################################################

:OrganizationRoleAssignment a owl:Class ;
    rdfs:label "Organization Role Assignment" ;
    rdfs:comment "Pivot class for relating an organization to a role in a specific invoice context." .

:InvoiceItemAssignment a owl:Class ;
    rdfs:label "Invoice Item Assignment" ;
    rdfs:comment "Pivot class for relating an invoice to a specific item and its details." .

:AllowanceChargeAssignment a owl:Class ;
    rdfs:label "Allowance Charge Assignment" ;
    rdfs:comment "Pivot class for relating an invoice to an allowance or charge." .

:DeliveryAssignment a owl:Class ;
    rdfs:label "Delivery Assignment" ;
    rdfs:comment "Pivot class for relating an invoice to delivery information." .

:TaxBreakdownAssignment a owl:Class ;
    rdfs:label "Tax Breakdown Assignment" ;
    rdfs:comment "Pivot class for relating an invoice to tax breakdown details." .

#################################################################
# SECTIONS AND LINE ITEMS
#################################################################

:HeaderSection a owl:Class ;
    rdfs:label "Header Section" ;
    rdfs:comment "The header section of an invoice message." .

:DetailSection a owl:Class ;
    rdfs:label "Detail Section" ;
    rdfs:comment "The detail (line items) section of an invoice message." .

:SummarySection a owl:Class ;
    rdfs:label "Summary Section" ;
    rdfs:comment "The summary section of an invoice message." .

:LineItem a owl:Class ;
    rdfs:label "Line Item" ;
    rdfs:comment "A line item within the detail section of an invoice." ;
    rdfs:subClassOf :DetailSection .

#################################################################
# PROPERTIES (OBJECT AND DATA)
#################################################################

:containsMessage a owl:ObjectProperty ;
    rdfs:domain :InterchangeEnvelope ;
    rdfs:range :Message ;
    rdfs:label "contains message" ;
    rdfs:comment "Relates an Interchange Envelope to the contained Message." ;
    owl:FunctionalProperty .

:hasSegment a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :Segment ;
    rdfs:label "has segment" ;
    rdfs:comment "Relates a Message to its constituent Segments." .

:hasBeginningOfMessage a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :BeginningOfMessage ;
    rdfs:label "has beginning of message" ;
    rdfs:comment "Links a Message to its BeginningOfMessage (BGM) segment." ;
    owl:FunctionalProperty .

:hasDateTimePeriod a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :DateTimePeriod ;
    rdfs:label "has date time period" ;
    rdfs:comment "Links a Message to its DTM segments." .

:hasReference a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :Reference ;
    rdfs:label "has reference" ;
    rdfs:comment "Links a Message to its RFF segments." .

:hasPriceSegment a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :PriceSegment ;
    rdfs:label "has price segment" ;
    rdfs:comment "Links a Message to its PRI segments." .

:hasQuantitySegment a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :QuantitySegment ;
    rdfs:label "has quantity segment" ;
    rdfs:comment "Links a Message to its QTY segments." .

:hasTaxSegment a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :TaxSegment ;
    rdfs:label "has tax segment" ;
    rdfs:comment "Links a Message to its TAX segments." .

:hasAllowanceChargeSegment a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :AllowanceChargeSegment ;
    rdfs:label "has allowance charge segment" ;
    rdfs:comment "Links a Message to its ALC segments." .

:hasSectionControl a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :SectionControl ;
    rdfs:label "has section control" ;
    rdfs:comment "Links a Message to its UNS (Section Control) segment." .

:identifiesInvoice a owl:ObjectProperty ;
    rdfs:domain :BeginningOfMessage ;
    rdfs:range :Invoice ;
    rdfs:label "identifies invoice" ;
    rdfs:comment "Relates the BGM segment to the Invoice it identifies." ;
    owl:FunctionalProperty .

:involvesOrganization a owl:ObjectProperty ;
    rdfs:domain :Invoice ;
    rdfs:range :OrganizationRoleAssignment ;
    rdfs:label "involves organization" ;
    rdfs:comment "Relates an Invoice to an OrganizationRoleAssignment pivot class." .

:hasRole a owl:ObjectProperty ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :AgentRole ;
    rdfs:label "has role" ;
    rdfs:comment "Assigns a specific AgentRole to an Organization within an Invoice." ;
    owl:FunctionalProperty .

:hasOrganization a owl:ObjectProperty ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :Organization ;
    rdfs:label "has organization" ;
    rdfs:comment "Links an OrganizationRoleAssignment to the Organization." ;
    owl:FunctionalProperty .

:hasAddress a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :Address ;
    rdfs:label "has address" ;
    rdfs:comment "Links an Organization to its Address." .

:hasIdentifier a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :Identifier ;
    rdfs:label "has identifier" ;
    rdfs:comment "Links an Organization to its Identifier (e.g., GLN)." .

:hasGlobalLocationNumber a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :GlobalLocationNumber ;
    rdfs:label "has GLN" ;
    rdfs:comment "Links an Organization to its Global Location Number." ;
    owl:FunctionalProperty .

:hasInvoiceItem a owl:ObjectProperty ;
    rdfs:domain :Invoice ;
    rdfs:range :InvoiceItemAssignment ;
    rdfs:label "has invoice item" ;
    rdfs:comment "Links an Invoice to its InvoiceItemAssignment pivot class." .

:hasItem a owl:ObjectProperty ;
    rdfs:domain :InvoiceItemAssignment ;
    rdfs:range :Item ;
    rdfs:label "has item" ;
    rdfs:comment "Assigns an Item to an InvoiceItemAssignment." ;
    owl:FunctionalProperty .

:hasPrice a owl:ObjectProperty ;
    rdfs:domain :InvoiceItemAssignment ;
    rdfs:range :Price ;
    rdfs:label "has price" ;
    rdfs:comment "Assigns a Price to an InvoiceItemAssignment." ;
    owl:FunctionalProperty .

:hasQuantity a owl:ObjectProperty ;
    rdfs:domain :InvoiceItemAssignment ;
    rdfs:range :Quantity ;
    rdfs:label "has quantity" ;
    rdfs:comment "Assigns a Quantity to an InvoiceItemAssignment." ;
    owl:FunctionalProperty .

:hasTax a owl:ObjectProperty ;
    rdfs:domain :InvoiceItemAssignment ;
    rdfs:range :Tax ;
    rdfs:label "has tax" ;
    rdfs:comment "Assigns a Tax to an InvoiceItemAssignment." ;
    owl:FunctionalProperty .

:hasBusinessProcess a owl:ObjectProperty ;
    rdfs:domain :Invoice ;
    rdfs:range :BusinessProcess ;
    rdfs:label "has business process" ;
    rdfs:comment "Assigns a BusinessProcess to an Invoice." ;
    owl:FunctionalProperty .

#################################################################
# DATA PROPERTIES
#################################################################

:invoiceAmount a owl:DatatypeProperty ;
    rdfs:domain :Invoice ;
    rdfs:range xsd:decimal ;
    rdfs:label "invoice amount" ;
    rdfs:comment "The total amount of the invoice." ;
    owl:FunctionalProperty .

:invoiceNumber a owl:DatatypeProperty ;
    rdfs:domain :Invoice ;
    rdfs:range xsd:string ;
    rdfs:label "invoice number" ;
    rdfs:comment "The unique number identifying the invoice." ;
    owl:FunctionalProperty .

:itemNetPrice a owl:DatatypeProperty ;
    rdfs:domain :Price ;
    rdfs:range xsd:decimal ;
    rdfs:label "item net price" ;
    rdfs:comment "The net price of an item in the invoice." ;
    owl:FunctionalProperty .

:itemQuantity a owl:DatatypeProperty ;
    rdfs:domain :Quantity ;
    rdfs:range xsd:integer ;
    rdfs:label "item quantity" ;
    rdfs:comment "The quantity of an item in the invoice." ;
    owl:FunctionalProperty .

:taxAmount a owl:DatatypeProperty ;
    rdfs:domain :Tax ;
    rdfs:range xsd:decimal ;
    rdfs:label "tax amount" ;
    rdfs:comment "The amount of tax applied to an item or invoice." ;
    owl:FunctionalProperty .

:addressLine a owl:DatatypeProperty ;
    rdfs:domain :Address ;
    rdfs:range xsd:string ;
    rdfs:label "address line" ;
    rdfs:comment "The street address or address line." .

:postalCode a owl:DatatypeProperty ;
    rdfs:domain :Address ;
    rdfs:range xsd:string ;
    rdfs:label "postal code" ;
    rdfs:comment "The postal code of an address." .

:city a owl:DatatypeProperty ;
    rdfs:domain :Address ;
    rdfs:range xsd:string ;
    rdfs:label "city" ;
    rdfs:comment "The city of an address." .

:country a owl:DatatypeProperty ;
    rdfs:domain :Address ;
    rdfs:range xsd:string ;
    rdfs:label "country" ;
    rdfs:comment "The country of an address." .

#################################################################
# MOA QUALIFIER-SPECIFIC CLASSES & PROPERTIES
#################################################################

:MOA79 a owl:Class ;
    rdfs:label "Invoice Line Net Amount (MOA+79)" ;
    rdfs:comment "Monetary amount for line net." ;
    rdfs:subClassOf :MonetaryAmountSegment .

:MOA86 a owl:Class ;
    rdfs:label "Line Item Amount (MOA+86)" ;
    rdfs:comment "Monetary amount for line item total." ;
    rdfs:subClassOf :MonetaryAmountSegment .

:MOA125 a owl:Class ;
    rdfs:label "Taxable Amount (MOA+125)" ;
    rdfs:comment "Taxable base amount." ;
    rdfs:subClassOf :MonetaryAmountSegment .

:MOA176 a owl:Class ;
    rdfs:label "Invoice Total Amount (MOA+176)" ;
    rdfs:comment "Total amount for the invoice." ;
    rdfs:subClassOf :MonetaryAmountSegment .

:MOA289 a owl:Class ;
    rdfs:label "Tax Base Amount (MOA+289)" ;
    rdfs:comment "Tax base amount for VAT, etc." ;
    rdfs:subClassOf :MonetaryAmountSegment .

:hasMOA79 a owl:ObjectProperty ;
    rdfs:domain :InvoiceItemAssignment ;
    rdfs:range :MOA79 ;
    rdfs:label "has MOA+79" ;
    rdfs:comment "Links a line item assignment to its MOA+79 (net amount)." .

:hasMOA86 a owl:ObjectProperty ;
    rdfs:domain :InvoiceItemAssignment ;
    rdfs:range :MOA86 ;
    rdfs:label "has MOA+86" ;
    rdfs:comment "Links a line item assignment to its MOA+86 (line item amount)." .

:hasMOA125 a owl:ObjectProperty ;
    rdfs:domain :Invoice ;
    rdfs:range :MOA125 ;
    rdfs:label "has MOA+125" ;
    rdfs:comment "Links an invoice to its MOA+125 (taxable amount)." .

:hasMOA176 a owl:ObjectProperty ;
    rdfs:domain :Invoice ;
    rdfs:range :MOA176 ;
    rdfs:label "has MOA+176" ;
    rdfs:comment "Links an invoice to its MOA+176 (total amount)." .

:hasMOA289 a owl:ObjectProperty ;
    rdfs:domain :Invoice ;
    rdfs:range :MOA289 ;
    rdfs:label "has MOA+289" ;
    rdfs:comment "Links an invoice to its MOA+289 (tax base amount)." .

#################################################################
# PROPERTY CHARACTERISTICS
#################################################################

:containsMessage a owl:FunctionalProperty .
:hasBeginningOfMessage a owl:FunctionalProperty .
:identifiesInvoice a owl:FunctionalProperty .
:hasRole a owl:FunctionalProperty .
:hasOrganization a owl:FunctionalProperty .
:hasGlobalLocationNumber a owl:FunctionalProperty .
:hasPrice a owl:FunctionalProperty .
:hasQuantity a owl:FunctionalProperty .
:hasTax a owl:FunctionalProperty .
:hasBusinessProcess a owl:FunctionalProperty .
:invoiceAmount a owl:FunctionalProperty .
:invoiceNumber a owl:FunctionalProperty .
:itemNetPrice a owl:FunctionalProperty .
:itemQuantity a owl:FunctionalProperty .
:taxAmount a owl:FunctionalProperty .

#################################################################
# DISJOINT CLASSES
#################################################################

:AgentRole owl:disjointWith :Organization .
:CompositeDataElement owl:disjointWith :SimpleDataElement .
:HeaderSection owl:disjointWith :DetailSection , :SummarySection .
:DetailSection owl:disjointWith :SummarySection .

