    rdfs:range :QuantitySegment ;
    rdfs:label "has quantity segment" ;
    rdfs:comment "Links a Message to its QTY segments." .

:hasTaxSegment a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :TaxSegment ;
    rdfs:label "has tax segment" ;
    rdfs:comment "Links a Message to its TAX segments." .

:hasAllowanceChargeSegment a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :AllowanceChargeSegment ;
    rdfs:label "has allowance charge segment" ;
    rdfs:comment "Links a Message to its ALC segments." .

:hasSectionControl a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :SectionControl ;
    rdfs:label "has section control" ;
    rdfs:comment "Links a Message to its UNS (Section Control) segment." .

:identifiesInvoice a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :BeginningOfMessage ;
    rdfs:range :Invoice ;
    rdfs:label "identifies invoice" ;
    rdfs:comment "Relates the BGM segment to the Invoice it identifies." .

:involvesOrganization a owl:ObjectProperty ;
    rdfs:domain :Invoice ;
    rdfs:range :OrganizationRoleAssignment ;
    rdfs:label "involves organization" ;
    rdfs:comment "Relates an Invoice to an OrganizationRoleAssignment pivot class." .

:hasRole a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :AgentRole ;
    rdfs:label "has role" ;
    rdfs:comment "Assigns a specific AgentRole to an Organization within an Invoice." .

:hasOrganization a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :Organization ;
    rdfs:label "has organization" ;
    rdfs:comment "Links an OrganizationRoleAssignment to the Organization." .

:hasAddress a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :Address ;
    rdfs:label "has address" ;
    rdfs:comment "Links an Organization to its Address." .

:hasIdentifier a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :Identifier ;
    rdfs:label "has identifier" ;
    rdfs:comment "Links an Organization to its Identifier (e.g., GLN)." .

:hasGlobalLocationNumber a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :Organization ;
    rdfs:range :GlobalLocationNumber ;
    rdfs:label "has GLN" ;
    rdfs:comment "Links an Organization to its Global Location Number." .

:hasInvoiceItem a owl:ObjectProperty ;
    rdfs:domain :Invoice ;
    rdfs:range :InvoiceItemAssignment ;
    rdfs:label "has invoice item" ;
    rdfs:comment "Links an Invoice to its InvoiceItemAssignment pivot class." .

:hasItem a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :InvoiceItemAssignment ;
    rdfs:range :Item ;
    rdfs:label "has item" ;
    rdfs:comment "Assigns an Item to an InvoiceItemAssignment." .

:hasPrice a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :InvoiceItemAssignment ;
    rdfs:range :Price ;
    rdfs:label "has price" ;
    rdfs:comment "Assigns a Price to an InvoiceItemAssignment." .

:hasQuantity a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :InvoiceItemAssignment ;
    rdfs:range :Quantity ;
    rdfs:label "has quantity" ;
    rdfs:comment "Assigns a Quantity to an InvoiceItemAssignment." .

:hasTax a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :InvoiceItemAssignment ;
    rdfs:range :Tax ;
    rdfs:label "has tax" ;
    rdfs:comment "Assigns a Tax to an InvoiceItemAssignment." .

:hasBusinessProcess a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :Invoice ;
    rdfs:range :BusinessProcess ;
    rdfs:label "has business process" ;
    rdfs:comment "Assigns a BusinessProcess to an Invoice." .

#################################################################
# DATA PROPERTIES
#################################################################

:invoiceAmount a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :Invoice ;
    rdfs:range xsd:decimal ;
    rdfs:label "invoice amount" ;
    rdfs:comment "The total amount of the invoice." .

:invoiceNumber a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :Invoice ;
    rdfs:range xsd:string ;
    rdfs:label "invoice number" ;
    rdfs:comment "The unique number identifying the invoice." .

:itemNetPrice a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :Price ;
    rdfs:range xsd:decimal ;
    rdfs:label "item net price" ;
    rdfs:comment "The net price of an item in the invoice." .

:itemQuantity a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :Quantity ;
    rdfs:range xsd:integer ;
    rdfs:label "item quantity" ;
    rdfs:comment "The quantity of an item in the invoice." .

:taxAmount a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :Tax ;
    rdfs:range xsd:decimal ;
    rdfs:label "tax amount" ;
    rdfs:comment "The amount of tax applied to an item or invoice." .

:addressLine a owl:DatatypeProperty ;
    rdfs:domain :Address ;
    rdfs:range xsd:string ;
    rdfs:label "address line" ;
    rdfs:comment "The street address or address line." .

:postalCode a owl:DatatypeProperty ;
    rdfs:domain :Address ;
    rdfs:range xsd:string ;
    rdfs:label "postal code" ;
    rdfs:comment "The postal code of an address." .

:city a owl:DatatypeProperty ;
    rdfs:domain :Address ;
    rdfs:range xsd:string ;
    rdfs:label "city" ;
    rdfs:comment "The city of an address." .

:country a owl:DatatypeProperty ;
    rdfs:domain :Address ;
    rdfs:range xsd:string ;
    rdfs:label "country" ;
    rdfs:comment "The country of an address." .

#################################################################
# MOA QUALIFIER-SPECIFIC CLASSES & PROPERTIES
#################################################################

:MOA79 a owl:Class ;
    rdfs:label "Invoice Line Net Amount (MOA+79)" ;
    rdfs:comment "Monetary amount for line net." ;
    rdfs:subClassOf :MonetaryAmountSegment .

:MOA86 a owl:Class ;
    rdfs:label "Line Item Amount (MOA+86)" ;
    rdfs:comment "Monetary amount for line item total." ;
    rdfs:subClassOf :MonetaryAmountSegment .

:MOA125 a owl:Class ;
    rdfs:label "Taxable Amount (MOA+125)" ;
    rdfs:comment "Taxable base amount." ;
    rdfs:subClassOf :MonetaryAmountSegment .

:MOA176 a owl:Class ;
    rdfs:label "Invoice Total Amount (MOA+176)" ;
    rdfs:comment "Total amount for the invoice." ;
    rdfs:subClassOf :MonetaryAmountSegment .

:MOA289 a owl:Class ;
    rdfs:label "Tax Base Amount (MOA+289)" ;
    rdfs:comment "Tax base amount for VAT, etc." ;
    rdfs:subClassOf :MonetaryAmountSegment .

:hasMOA79 a owl:ObjectProperty ;
    rdfs:domain :InvoiceItemAssignment ;
    rdfs:range :MOA79 ;
    rdfs:label "has MOA+79" ;
    rdfs:comment "Links a line item assignment to its MOA+79 (net amount)." .

:hasMOA86 a owl:ObjectProperty ;
    rdfs:domain :InvoiceItemAssignment ;
    rdfs:range :MOA86 ;
    rdfs:label "has MOA+86" ;
    rdfs:comment "Links a line item assignment to its MOA+86 (line item amount)." .

:hasMOA125 a owl:ObjectProperty ;
    rdfs:domain :Invoice ;
    rdfs:range :MOA125 ;
    rdfs:label "has MOA+125" ;
    rdfs:comment "Links an invoice to its MOA+125 (taxable amount)." .

:hasMOA176 a owl:ObjectProperty ;
    rdfs:domain :Invoice ;
    rdfs:range :MOA176 ;
    rdfs:label "has MOA+176" ;
    rdfs:comment "Links an invoice to its MOA+176 (total amount)." .

:hasMOA289 a owl:ObjectProperty ;
    rdfs:domain :Invoice ;
    rdfs:range :MOA289 ;
    rdfs:label "has MOA+289" ;
    rdfs:comment "Links an invoice to its MOA+289 (tax base amount)." .

#################################################################
# DISJOINT CLASSES
#################################################################

:AgentRole owl:disjointWith :Organization .
:CompositeDataElement owl:disjointWith :SimpleDataElement .
:HeaderSection owl:disjointWith :DetailSection , :SummarySection .
:DetailSection owl:disjointWith :SummarySection .
"}

args.value:
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

<http://www.example.org/ontology#EDIFACT-INVOIC-Ontology> a owl:Ontology ;
    rdfs:label "EDIFACT INVOIC Profound Ontology" ;
    rdfs:comment "A comprehensive OWL2 ontology for the structure of EDIFACT D96A INVOIC messages, supporting EN 16931-1, P2P-O alignment, and SHACL validation." .

#################################################################
# CORE CLASSES
#################################################################

:InterchangeEnvelope a owl:Class ;
    rdfs:label "Interchange Envelope" ;
    rdfs:comment "The top-level UN/EDIFACT envelope containing one or more messages." .

:Message a owl:Class ;
    rdfs:label "Message" ;
    rdfs:comment "A business message such as INVOIC within the Interchange Envelope." .

:Segment a owl:Class ;
    rdfs:label "Segment" ;
    rdfs:comment "A generic EDIFACT segment, the building block of a message." .

:CompositeDataElement a owl:Class ;
    rdfs:label "Composite Data Element" ;
    rdfs:comment "A composite data element within a segment." ;
    rdfs:subClassOf :Segment .

:SimpleDataElement a owl:Class ;
    rdfs:label "Simple Data Element" ;
    rdfs:comment "A simple data element within a composite or segment." ;
    rdfs:subClassOf :Segment .

:Invoice a owl:Class ;
    rdfs:label "Invoice" ;
    rdfs:comment "An invoice document, represented as an INVOIC message." ;
    rdfs:subClassOf :Message .

:Organization a owl:Class ;
    rdfs:label "Organization" ;
    rdfs:comment "A business entity involved in the invoice (buyer, seller, delivery party, etc.)." .

:AgentRole a owl:Class ;
    rdfs:label "Agent Role" ;
    rdfs:comment "A specific role played by an organization in the context of an invoice (e.g., Buyer, Supplier, Delivery Party)." .

:Address a owl:Class ;
    rdfs:label "Address" ;
    rdfs:comment "A postal or physical address related to an organization." .

:Identifier a owl:Class ;
    rdfs:label "Identifier" ;
    rdfs:comment "A generic identifier such as a Global Location Number." .

:GlobalLocationNumber a owl:Class ;
    rdfs:label "Global Location Number" ;
    rdfs:comment "A unique identifier for an organization location, e.g., GLN." ;
    rdfs:subClassOf :Identifier .

:Item a owl:Class ;
    rdfs:label "Item" ;
    rdfs:comment "A product or service listed in the invoice." .

:Price a owl:Class ;
    rdfs:label "Price" ;
    rdfs:comment "A price value associated with an item or invoice." .

:Quantity a owl:Class ;
    rdfs:label "Quantity" ;
    rdfs:comment "A quantity value for an item or invoice." .

:Tax a owl:Class ;
    rdfs:label "Tax" ;
    rdfs:comment "A tax concept applied to an item or invoice." .

:BusinessProcess a owl:Class ;
    rdfs:label "Business Process" ;
    rdfs:comment "A business process to which the invoice can be assigned." .

#################################################################
# SEGMENT-LEVEL AND PIVOT CLASSES
#################################################################

:BeginningOfMessage a owl:Class ;
    rdfs:label "Beginning of Message Segment (BGM)" ;
    rdfs:comment "The BGM segment, identifying the type and number of the document." ;
    rdfs:subClassOf :Segment .

:DateTimePeriod a owl:Class ;
    rdfs:label "Date/Time/Period Segment (DTM)" ;
    rdfs:comment "A DTM segment specifying a relevant date or period (e.g., invoice date, delivery date)." ;
    rdfs:subClassOf :Segment .

:Reference a owl:Class ;
    rdfs:label "Reference Segment (RFF)" ;
    rdfs:comment "A reference segment for document numbers, order references, etc." ;
    rdfs:subClassOf :Segment .

:PriceSegment a owl:Class ;
    rdfs:label "Price Segment (PRI)" ;
    rdfs:comment "A PRI segment specifying price details for line items." ;
    rdfs:subClassOf :Segment .

:QuantitySegment a owl:Class ;
    rdfs:label "Quantity Segment (QTY)" ;
    rdfs:comment "A QTY segment specifying quantity details for line items." ;
    rdfs:subClassOf :Segment .

:TaxSegment a owl:Class ;
    rdfs:label "Tax Segment (TAX)" ;
    rdfs:comment "A TAX segment specifying tax details for invoice or line items." ;
    rdfs:subClassOf :Segment .

:AllowanceChargeSegment a owl:Class ;
    rdfs:label "Allowance/Charge Segment (ALC)" ;
    rdfs:comment "An ALC segment specifying allowances or charges." ;
    rdfs:subClassOf :Segment .

:SectionControl a owl:Class ;
    rdfs:label "Section Control Segment (UNS)" ;
    rdfs:comment "A UNS segment marking section boundaries in the message." ;
    rdfs:subClassOf :Segment .

:MonetaryAmountSegment a owl:Class ;
    rdfs:label "Monetary Amount Segment (MOA)" ;
    rdfs:comment "A MOA segment with a specific qualifier (e.g. MOA+79, MOA+86, MOA+125, MOA+176, MOA+289)." ;
    rdfs:subClassOf :Segment .

:MeasurementSegment a owl:Class ;
    rdfs:label "Measurement Segment (MEA)" ;
    rdfs:comment "A MEA segment specifying measurements (e.g., weight, volume)." ;
    rdfs:subClassOf :Segment .

:PackagingSegment a owl:Class ;
    rdfs:label "Packaging Segment (PAC)" ;
    rdfs:comment "A PAC segment specifying packaging details." ;
    rdfs:subClassOf :Segment .

:TransportSegment a owl:Class ;
    rdfs:label "Transport Segment (TOD)" ;
    rdfs:comment "A TOD segment specifying transport arrangements." ;
    rdfs:subClassOf :Segment .

#################################################################
# REIFICATION/PIVOT CLASSES
#################################################################

:OrganizationRoleAssignment a owl:Class ;
    rdfs:label "Organization Role Assignment" ;
    rdfs:comment "Pivot class for relating an organization to a role in a specific invoice context." .

:InvoiceItemAssignment a owl:Class ;
    rdfs:label "Invoice Item Assignment" ;
    rdfs:comment "Pivot class for relating an invoice to a specific item and its details." .

:AllowanceChargeAssignment a owl:Class ;
    rdfs:label "Allowance Charge Assignment" ;
    rdfs:comment "Pivot class for relating an invoice to an allowance or charge." .

:DeliveryAssignment a owl:Class ;
    rdfs:label "Delivery Assignment" ;
    rdfs:comment "Pivot class for relating an invoice to delivery information." .

:TaxBreakdownAssignment a owl:Class ;
    rdfs:label "Tax Breakdown Assignment" ;
    rdfs:comment "Pivot class for relating an invoice to tax breakdown details." .

#################################################################
# SECTIONS AND LINE ITEMS
#################################################################

:HeaderSection a owl:Class ;
    rdfs:label "Header Section" ;
    rdfs:comment "The header section of an invoice message." .

:DetailSection a owl:Class ;
    rdfs:label "Detail Section" ;
    rdfs:comment "The detail (line items) section of an invoice message." .

:SummarySection a owl:Class ;
    rdfs:label "Summary Section" ;
    rdfs:comment "The summary section of an invoice message." .

:LineItem a owl:Class ;
    rdfs:label "Line Item" ;
    rdfs:comment "A line item within the detail section of an invoice." ;
    rdfs:subClassOf :DetailSection .

#################################################################
# PROPERTIES (OBJECT AND DATA)
#################################################################

:containsMessage a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :InterchangeEnvelope ;
    rdfs:range :Message ;
    rdfs:label "contains message" ;
    rdfs:comment "Relates an Interchange Envelope to the contained Message." .
    owl:inverseOf :isMessageContainedIn .

:isMessageContainedIn a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :InterchangeEnvelope ;
    rdfs:label "is message contained in" ;
    rdfs:comment "Inverse of containsMessage." .

:hasSegment a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :Segment ;
    rdfs:label "has segment" ;
    rdfs:comment "Relates a Message to its constituent Segments." ;
    owl:inverseOf :isSegmentOfMessage .

:isSegmentOfMessage a owl:ObjectProperty ;
    rdfs:domain :Segment ;
    rdfs:range :Message ;
    rdfs:label "is segment of message" ;
    rdfs:comment "Inverse of hasSegment." .

:hasBeginningOfMessage a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :Message ;
    rdfs:range :BeginningOfMessage ;
    rdfs:label "has beginning of message" ;
    rdfs:comment "Links a Message to its BeginningOfMessage (BGM) segment." ;
    owl:inverseOf :isBeginningOfMessageOf .

:isBeginningOfMessageOf a owl:ObjectProperty ;
    rdfs:domain :BeginningOfMessage ;
    rdfs:range :Message ;
    rdfs:label "is beginning of message of" ;
    rdfs:comment "Inverse of hasBeginningOfMessage." .

:hasDateTimePeriod a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :DateTimePeriod ;
    rdfs:label "has date time period" ;
    rdfs:comment "Links a Message to its DTM segments." ;
    owl:inverseOf :isDateTimePeriodOfMessage .

:isDateTimePeriodOfMessage a owl:ObjectProperty ;
    rdfs:domain :DateTimePeriod ;
    rdfs:range :Message ;
    rdfs:label "is date time period of message" ;
    rdfs:comment "Inverse of hasDateTimePeriod." .

:hasReference a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :Reference ;
    rdfs:label "has reference" ;
    rdfs:comment "Links a Message to its RFF segments." ;
    owl:inverseOf :isReferenceOfMessage .

:isReferenceOfMessage a owl:ObjectProperty ;
    rdfs:domain :Reference ;
    rdfs:range :Message ;
    rdfs:label "is reference of message" ;
    rdfs:comment "Inverse of hasReference." .

:hasPriceSegment a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :PriceSegment ;
    rdfs:label "has price segment" ;
    rdfs:comment "Links a Message to its PRI segments." ;
    owl:inverseOf :isPriceSegmentOfMessage .

:isPriceSegmentOfMessage a owl:ObjectProperty ;
    rdfs:domain :PriceSegment ;
    rdfs:range :Message ;
    rdfs:label "is price segment of message" ;
    rdfs:comment "Inverse of hasPriceSegment." .

:hasQuantitySegment a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :QuantitySegment ;
    rdfs:label "has quantity segment" ;
    rdfs:comment "Links a Message to its QTY segments." ;
    owl:inverseOf :isQuantitySegmentOfMessage .

:isQuantitySegmentOfMessage a owl:ObjectProperty ;
    rdfs:domain :QuantitySegment ;
    rdfs:range :Message ;
    rdfs:label "is quantity segment of message" ;
    rdfs:comment "Inverse of hasQuantitySegment." .

:hasTaxSegment a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :TaxSegment ;
    rdfs:label "has tax segment" ;
    rdfs:comment "Links a Message to its TAX segments." ;
    owl:inverseOf :isTaxSegmentOfMessage .

:isTaxSegmentOfMessage a owl:ObjectProperty ;
    rdfs:domain :TaxSegment ;
    rdfs:range :Message ;
    rdfs:label "is tax segment of message" ;
    rdfs:comment "Inverse of hasTaxSegment." .

:hasAllowanceChargeSegment a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :AllowanceChargeSegment ;
    rdfs:label "has allowance charge segment" ;
    rdfs:comment "Links a Message to its ALC segments." ;
    owl:inverseOf :isAllowanceChargeSegmentOfMessage .

:isAllowanceChargeSegmentOfMessage a owl:ObjectProperty ;
    rdfs:domain :AllowanceChargeSegment ;
    rdfs:range :Message ;
    rdfs:label "is allowance charge segment of message" ;
    rdfs:comment "Inverse of hasAllowanceChargeSegment." .

:hasSectionControl a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :SectionControl ;
    rdfs:label "has section control" ;
    rdfs:comment "Links a Message to its UNS (Section Control) segment." ;
    owl:inverseOf :isSectionControlOfMessage .

:isSectionControlOfMessage a owl:ObjectProperty ;
    rdfs:domain :SectionControl ;
    rdfs:range :Message ;
    rdfs:label "is section control of message" ;
    rdfs:comment "Inverse of hasSectionControl." .

:identifiesInvoice a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :BeginningOfMessage ;
    rdfs:range :Invoice ;
    rdfs:label "identifies invoice" ;
    rdfs:comment "Relates the BGM segment to the Invoice it identifies." ;
    owl:inverseOf :isInvoiceIdentifiedBy .

:isInvoiceIdentifiedBy a owl:ObjectProperty ;
    rdfs:domain :Invoice ;
    rdfs:range :BeginningOfMessage ;
    rdfs:label "is invoice identified by" ;
    rdfs:comment "Inverse of identifiesInvoice." .

:involvesOrganization a owl:ObjectProperty ;
    rdfs:domain :Invoice ;
    rdfs:range :OrganizationRoleAssignment ;
    rdfs:label "involves organization" ;
    rdfs:comment "Relates an Invoice to an OrganizationRoleAssignment pivot class." ;
    owl:inverseOf :isOrganizationInvolvedIn .

:isOrganizationInvolvedIn a owl:ObjectProperty ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :Invoice ;
    rdfs:label "is organization involved in" ;
    rdfs:comment "Inverse of involvesOrganization." .

:hasRole a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :AgentRole ;
    rdfs:label "has role" ;
    rdfs:comment "Assigns a specific AgentRole to an Organization within an Invoice." ;
    owl:inverseOf :isRoleOfAssignment .

:isRoleOfAssignment a owl:ObjectProperty ;
    rdfs:domain :AgentRole ;
    rdfs:range :OrganizationRoleAssignment ;
    rdfs:label "is role of assignment" ;
    rdfs:comment "Inverse of hasRole." .

:hasOrganization a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :Organization ;
    rdfs:label "has organization" ;
    rdfs:comment "Links an OrganizationRoleAssignment to the Organization." ;
    owl:inverseOf :isOrganizationOfAssignment .

:isOrganizationOfAssignment a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :OrganizationRoleAssignment ;
    rdfs:label "is organization of assignment" ;
    rdfs:comment "Inverse of hasOrganization." .

:hasAddress a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :Address ;
    rdfs:label "has address" ;
    rdfs:comment "Links an Organization to its Address." ;
    owl:inverseOf :isAddressOfOrganization .

:isAddressOfOrganization a owl:ObjectProperty ;
    rdfs:domain :Address ;
    rdfs:range :Organization ;
    rdfs:label "is address of organization" ;
    rdfs:comment "Inverse of hasAddress." .

:hasIdentifier a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :Identifier ;
    rdfs:label "has identifier" ;
    rdfs:comment "Links an Organization to its Identifier (e.g., GLN)." ;
    owl:inverseOf :isIdentifierOfOrganization .

:isIdentifierOfOrganization a owl:ObjectProperty ;
    rdfs:domain :Identifier ;
    rdfs:range :Organization ;
    rdfs:label "is identifier of organization" ;
    rdfs:comment "Inverse of hasIdentifier." .

:hasGlobalLocationNumber a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :Organization ;
    rdfs:range :GlobalLocationNumber ;
    rdfs:label "has GLN" ;
    rdfs:comment "Links an Organization to its Global Location Number." ;
    owl:inverseOf :isGLNOfOrganization .

:isGLNOfOrganization a owl:ObjectProperty ;
    rdfs:domain :GlobalLocationNumber ;
    rdfs:range :Organization ;
    rdfs:label "is GLN of organization" ;
    rdfs:comment "Inverse of hasGlobalLocationNumber." .

:hasInvoiceItem a owl:ObjectProperty ;
    rdfs:domain :Invoice ;
    rdfs:range :InvoiceItemAssignment ;
    rdfs:label "has invoice item" ;
    rdfs:comment "Links an Invoice to its InvoiceItemAssignment pivot class." ;
    owl:inverseOf :isInvoiceItemOf .

:isInvoiceItemOf a owl:ObjectProperty ;
    rdfs:domain :InvoiceItemAssignment ;
    rdfs:range :Invoice ;
    rdfs:label "is invoice item of" ;
    rdfs:comment "Inverse of hasInvoiceItem." .

:hasItem a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :InvoiceItemAssignment ;
    rdfs:range :Item ;
    rdfs:label "has item" ;
    rdfs:comment "Assigns an Item to an InvoiceItemAssignment." ;
    owl:inverseOf :isItemOfAssignment .

:isItemOfAssignment a owl:ObjectProperty ;
    rdfs:domain :Item ;
    rdfs:range :InvoiceItemAssignment ;
    rdfs:label "is item of assignment" ;
    rdfs:comment "Inverse of hasItem." .

:hasPrice a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :InvoiceItemAssignment ;
    rdfs:range :Price ;
    rdfs:label "has price" ;
    rdfs:comment "Assigns a Price to an InvoiceItemAssignment." ;
    owl:inverseOf :isPriceOfAssignment .

:isPriceOfAssignment a owl:ObjectProperty ;
    rdfs:domain :Price ;
    rdfs:range :InvoiceItemAssignment ;
    rdfs:label "is price of assignment" ;
    rdfs:comment "Inverse of hasPrice." .

:hasQuantity a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :InvoiceItemAssignment ;
    rdfs:range :Quantity ;
    rdfs:label "has quantity" ;
    rdfs:comment "Assigns a Quantity to an InvoiceItemAssignment." ;
    owl:inverseOf :isQuantityOfAssignment .

:isQuantityOfAssignment a owl:ObjectProperty ;
    rdfs:domain :Quantity ;
    rdfs:range :InvoiceItemAssignment ;
    rdfs:label "is quantity of assignment" ;
    rdfs:comment "Inverse of hasQuantity." .

:hasTax a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :InvoiceItemAssignment ;
    rdfs:range :Tax ;
    rdfs:label "has tax" ;
    rdfs:comment "Assigns a Tax to an InvoiceItemAssignment." ;
    owl:inverseOf :isTaxOfAssignment .

:isTaxOfAssignment a owl:ObjectProperty ;
    rdfs:domain :Tax ;
    rdfs:range :InvoiceItemAssignment ;
    rdfs:label "is tax of assignment" ;
    rdfs:comment "Inverse of hasTax." .

:hasBusinessProcess a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :Invoice ;
    rdfs:range :BusinessProcess ;
    rdfs:label "has business process" ;
    rdfs:comment "Assigns a BusinessProcess to an Invoice." ;
    owl:inverseOf :isBusinessProcessOf .

:isBusinessProcessOf a owl:ObjectProperty ;
    rdfs:domain :BusinessProcess ;
    rdfs:range :Invoice ;
    rdfs:label "is business process of" ;
    rdfs:comment "Inverse of hasBusinessProcess." .

# Section and Assignment Connections (fixing P04)
:hasHeaderSection a owl:ObjectProperty ;
    rdfs:domain :Invoice ;
    rdfs:range :HeaderSection ;
    rdfs:label "has header section" ;
    rdfs:comment "Connects an Invoice to its HeaderSection." ;
    owl:inverseOf :isHeaderSectionOf .

:isHeaderSectionOf a owl:ObjectProperty ;
    rdfs:domain :HeaderSection ;
    rdfs:range :Invoice ;
    rdfs:label "is header section of" ;
    rdfs:comment "Inverse of hasHeaderSection." .

:hasDetailSection a owl:ObjectProperty ;
    rdfs:domain :Invoice ;
    rdfs:range :DetailSection ;
    rdfs:label "has detail section" ;
    rdfs:comment "Connects an Invoice to its DetailSection." ;
    owl:inverseOf :isDetailSectionOf .

:isDetailSectionOf a owl:ObjectProperty ;
    rdfs:domain :DetailSection ;
    rdfs:range :Invoice ;
    rdfs:label "is detail section of" ;
    rdfs:comment "Inverse of hasDetailSection." .

:hasSummarySection a owl:ObjectProperty ;
    rdfs:domain :Invoice ;
    rdfs:range :SummarySection ;
    rdfs:label "has summary section" ;
    rdfs:comment "Connects an Invoice to its SummarySection." ;
    owl:inverseOf :isSummarySectionOf .

:isSummarySectionOf a owl:ObjectProperty ;
    rdfs:domain :SummarySection ;
    rdfs:range :Invoice ;
    rdfs:label "is summary section of" ;
    rdfs:comment "Inverse of hasSummarySection." .

:hasDeliveryAssignment a owl:ObjectProperty ;
    rdfs:domain :Invoice ;
    rdfs:range :DeliveryAssignment ;
    rdfs:label "has delivery assignment" ;
    rdfs:comment "Connects an Invoice to its DeliveryAssignment." ;
    owl:inverseOf :isDeliveryAssignmentOf .

:isDeliveryAssignmentOf a owl:ObjectProperty ;
    rdfs:domain :DeliveryAssignment ;
    rdfs:range :Invoice ;
    rdfs:label "is delivery assignment of" ;
    rdfs:comment "Inverse of hasDeliveryAssignment." .

:hasAllowanceChargeAssignment a owl:ObjectProperty ;
    rdfs:domain :Invoice ;
    rdfs:range :AllowanceChargeAssignment ;
    rdfs:label "has allowance charge assignment" ;
    rdfs:comment "Connects an Invoice to its AllowanceChargeAssignment." ;
    owl:inverseOf :isAllowanceChargeAssignmentOf .

:isAllowanceChargeAssignmentOf a owl:ObjectProperty ;
    rdfs:domain :AllowanceChargeAssignment ;
    rdfs:range :Invoice ;
    rdfs:label "is allowance charge assignment of" ;
    rdfs:comment "Inverse of hasAllowanceChargeAssignment." .

:hasTaxBreakdownAssignment a owl:ObjectProperty ;
    rdfs:domain :Invoice ;
    rdfs:range :TaxBreakdownAssignment ;
    rdfs:label "has tax breakdown assignment" ;
    rdfs:comment "Connects an Invoice to its TaxBreakdownAssignment." ;
    owl:inverseOf :isTaxBreakdownAssignmentOf .

:isTaxBreakdownAssignmentOf a owl:ObjectProperty ;
    rdfs:domain :TaxBreakdownAssignment ;
    rdfs:range :Invoice ;
    rdfs:label "is tax breakdown assignment of" ;
    rdfs:comment "Inverse of hasTaxBreakdownAssignment." .

#################################################################
# DATA PROPERTIES
#################################################################

:invoiceAmount a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :Invoice ;
    rdfs:range xsd:decimal ;
    rdfs:label "invoice amount" ;
    rdfs:comment "The total amount of the invoice." .

:invoiceNumber a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :Invoice ;
    rdfs:range xsd:string ;
    rdfs:label "invoice number" ;
    rdfs:comment "The unique number identifying the invoice." .

:itemNetPrice a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :Price ;
    rdfs:range xsd:decimal ;
    rdfs:label "item net price" ;
    rdfs:comment "The net price of an item in the invoice." .

:itemQuantity a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :Quantity ;
    rdfs:range xsd:integer ;
    rdfs:label "item quantity" ;
    rdfs:comment "The quantity of an item in the invoice." .

:taxAmount a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :Tax ;
    rdfs:range xsd:decimal ;
    rdfs:label "tax amount" ;
    rdfs:comment "The amount of tax applied to an item or invoice." .

:addressLine a owl:DatatypeProperty ;
    rdfs:domain :Address ;
    rdfs:range xsd:string ;
    rdfs:label "address line" ;
    rdfs:comment "The street address or address line." .

:postalCode a owl:DatatypeProperty ;
    rdfs:domain :Address ;
    rdfs:range xsd:string ;
    rdfs:label "postal code" ;
    rdfs:comment "The postal code of an address." .

:city a owl:DatatypeProperty ;
    rdfs:domain :Address ;
    rdfs:range xsd:string ;
    rdfs:label "city" ;
    rdfs:comment "The city of an address." .

:country a owl:DatatypeProperty ;
    rdfs:domain :Address ;
    rdfs:range xsd:string ;
    rdfs:label "country" ;
    rdfs:comment "The country of an address." .

#################################################################
# MOA QUALIFIER-SPECIFIC CLASSES & PROPERTIES
#################################################################

:MOA79 a owl:Class ;
    rdfs:label "Invoice Line Net Amount (MOA+79)" ;
    rdfs:comment "Monetary amount for line net." ;
    rdfs:subClassOf :MonetaryAmountSegment .

:MOA86 a owl:Class ;
    rdfs:label "Line Item Amount (MOA+86)" ;
    rdfs:comment "Monetary amount for line item total." ;
    rdfs:subClassOf :MonetaryAmountSegment .

:MOA125 a owl:Class ;
    rdfs:label "Taxable Amount (MOA+125)" ;
    rdfs:comment "Taxable base amount." ;
    rdfs:subClassOf :MonetaryAmountSegment .

:MOA176 a owl:Class ;
    rdfs:label "Invoice Total Amount (MOA+176)" ;
    rdfs:comment "Total amount for the invoice." ;
    rdfs:subClassOf :MonetaryAmountSegment .

:MOA289 a owl:Class ;
    rdfs:label "Tax Base Amount (MOA+289)" ;
    rdfs:comment "Tax base amount for VAT, etc." ;
    rdfs:subClassOf :MonetaryAmountSegment .

:hasMOA79 a owl:ObjectProperty ;
    rdfs:domain :InvoiceItemAssignment ;
    rdfs:range :MOA79 ;
    rdfs:label "has MOA+79" ;
    rdfs:comment "Links a line item assignment to its MOA+79 (net amount)." ;
    owl:inverseOf :isMOA79Of .

:isMOA79Of a owl:ObjectProperty ;
    rdfs:domain :MOA79 ;
    rdfs:range :InvoiceItemAssignment ;
    rdfs:label "is MOA+79 of" ;
    rdfs:comment "Inverse of hasMOA79." .

:hasMOA86 a owl:ObjectProperty ;
    rdfs:domain :InvoiceItemAssignment ;
    rdfs:range :MOA86 ;
    rdfs:label "has MOA+86" ;
    rdfs:comment "Links a line item assignment to its MOA+86 (line item amount)." ;
    owl:inverseOf :isMOA86Of .

:isMOA86Of a owl:ObjectProperty ;
    rdfs:domain :MOA86 ;
    rdfs:range :InvoiceItemAssignment ;
    rdfs:label "is MOA+86 of" ;
    rdfs:comment "Inverse of hasMOA86." .

:hasMOA125 a owl:ObjectProperty ;
    rdfs:domain :Invoice ;
    rdfs:range :MOA125 ;
    rdfs:label "has MOA+125" ;
    rdfs:comment "Links an invoice to its MOA+125 (taxable amount)." ;
    owl:inverseOf :isMOA125Of .

:isMOA125Of a owl:ObjectProperty ;
    rdfs:domain :MOA125 ;
    rdfs:range :Invoice ;
    rdfs:label "is MOA+125 of" ;
    rdfs:comment "Inverse of hasMOA125." .

:hasMOA176 a owl:ObjectProperty ;
    rdfs:domain :Invoice ;
    rdfs:range :MOA176 ;
    rdfs:label "has MOA+176" ;
    rdfs:comment "Links an invoice to its MOA+176 (total amount)." ;
    owl:inverseOf :isMOA176Of .

:isMOA176Of a owl:ObjectProperty ;
    rdfs:domain :MOA176 ;
    rdfs:range :Invoice ;
    rdfs:label "is MOA+176 of" ;
    rdfs:comment "Inverse of hasMOA176." .

:hasMOA289 a owl:ObjectProperty ;
    rdfs:domain :Invoice ;
    rdfs:range :MOA289 ;
    rdfs:label "has MOA+289" ;
    rdfs:comment "Links an invoice to its MOA+289 (tax base amount)." ;
    owl:inverseOf :isMOA289Of .

:isMOA289Of a owl:ObjectProperty ;
    rdfs:domain :MOA289 ;
    rdfs:range :Invoice ;
    rdfs:label "is MOA+289 of" ;
    rdfs:comment "Inverse of hasMOA289." .

#################################################################
# DISJOINT CLASSES
#################################################################

:AgentRole owl:disjointWith :Organization .
:CompositeDataElement owl:disjointWith :SimpleDataElement .
:HeaderSection owl:disjointWith :DetailSection , :SummarySection .
:DetailSection owl:disjointWith :SummarySection .

function.arguments:
{"key":"current_owl","value":"@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

<http://www.example.org/ontology#EDIFACT-INVOIC-Ontology> a owl:Ontology ;
    rdfs:label "EDIFACT INVOIC Profound Ontology" ;
    rdfs:comment "A comprehensive OWL2 ontology for the structure of EDIFACT D96A INVOIC messages, supporting EN 16931-1, P2P-O alignment, and SHACL validation." .

#################################################################
# CORE CLASSES
#################################################################

:InterchangeEnvelope a owl:Class ;
    rdfs:label "Interchange Envelope" ;
    rdfs:comment "The top-level UN/EDIFACT envelope containing one or more messages." .

:Message a owl:Class ;
    rdfs:label "Message" ;
    rdfs:comment "A business message such as INVOIC within the Interchange Envelope." .

:Segment a owl:Class ;
    rdfs:label "Segment" ;
    rdfs:comment "A generic EDIFACT segment, the building block of a message." .

:CompositeDataElement a owl:Class ;
    rdfs:label "Composite Data Element" ;
    rdfs:comment "A composite data element within a segment." ;
    rdfs:subClassOf :Segment .

:SimpleDataElement a owl:Class ;
    rdfs:label "Simple Data Element" ;
    rdfs:comment "A simple data element within a composite or segment." ;
    rdfs:subClassOf :Segment .

:Invoice a owl:Class ;
    rdfs:label "Invoice" ;
    rdfs:comment "An invoice document, represented as an INVOIC message." ;
    rdfs:subClassOf :Message .

:Organization a owl:Class ;
    rdfs:label "Organization" ;
    rdfs:comment "A business entity involved in the invoice (buyer, seller, delivery party, etc.)." .

:AgentRole a owl:Class ;
    rdfs:label "Agent Role" ;
    rdfs:comment "A specific role played by an organization in the context of an invoice (e.g., Buyer, Supplier, Delivery Party)." .

:Address a owl:Class ;
    rdfs:label "Address" ;
    rdfs:comment "A postal or physical address related to an organization." .

:Identifier a owl:Class ;
    rdfs:label "Identifier" ;
    rdfs:comment "A generic identifier such as a Global Location Number." .

:GlobalLocationNumber a owl:Class ;
    rdfs:label "Global Location Number" ;
    rdfs:comment "A unique identifier for an organization location, e.g., GLN." ;
    rdfs:subClassOf :Identifier .

:Item a owl:Class ;
    rdfs:label "Item" ;
    rdfs:comment "A product or service listed in the invoice." .

:Price a owl:Class ;
    rdfs:label "Price" ;
    rdfs:comment "A price value associated with an item or invoice." .

:Quantity a owl:Class ;
    rdfs:label "Quantity" ;
    rdfs:comment "A quantity value for an item or invoice." .

:Tax a owl:Class ;
    rdfs:label "Tax" ;
    rdfs:comment "A tax concept applied to an item or invoice." .

:BusinessProcess a owl:Class ;
    rdfs:label "Business Process" ;
    rdfs:comment "A business process to which the invoice can be assigned." .

#################################################################
# SEGMENT-LEVEL AND PIVOT CLASSES
#################################################################

:BeginningOfMessage a owl:Class ;
    rdfs:label "Beginning of Message Segment (BGM)" ;
    rdfs:comment "The BGM segment, identifying the type and number of the document." ;
    rdfs:subClassOf :Segment .

:DateTimePeriod a owl:Class ;
    rdfs:label "Date/Time/Period Segment (DTM)" ;
    rdfs:comment "A DTM segment specifying a relevant date or period (e.g., invoice date, delivery date)." ;
    rdfs:subClassOf :Segment .

:Reference a owl:Class ;
    rdfs:label "Reference Segment (RFF)" ;
    rdfs:comment "A reference segment for document numbers, order references, etc." ;
    rdfs:subClassOf :Segment .

:PriceSegment a owl:Class ;
    rdfs:label "Price Segment (PRI)" ;
    rdfs:comment "A PRI segment specifying price details for line items." ;
    rdfs:subClassOf :Segment .

:QuantitySegment a owl:Class ;
    rdfs:label "Quantity Segment (QTY)" ;
    rdfs:comment "A QTY segment specifying quantity details for line items." ;
    rdfs:subClassOf :Segment .

:TaxSegment a owl:Class ;
    rdfs:label "Tax Segment (TAX)" ;
    rdfs:comment "A TAX segment specifying tax details for invoice or line items." ;
    rdfs:subClassOf :Segment .

:AllowanceChargeSegment a owl:Class ;
    rdfs:label "Allowance/Charge Segment (ALC)" ;
    rdfs:comment "An ALC segment specifying allowances or charges." ;
    rdfs:subClassOf :Segment .

:SectionControl a owl:Class ;
    rdfs:label "Section Control Segment (UNS)" ;
    rdfs:comment "A UNS segment marking section boundaries in the message." ;
    rdfs:subClassOf :Segment .

:MonetaryAmountSegment a owl:Class ;
    rdfs:label "Monetary Amount Segment (MOA)" ;
    rdfs:comment "A MOA segment with a specific qualifier (e.g. MOA+79, MOA+86, MOA+125, MOA+176, MOA+289)." ;
    rdfs:subClassOf :Segment .

:MeasurementSegment a owl:Class ;
    rdfs:label "Measurement Segment (MEA)" ;
    rdfs:comment "A MEA segment specifying measurements (e.g., weight, volume)." ;
    rdfs:subClassOf :Segment .

:PackagingSegment a owl:Class ;
    rdfs:label "Packaging Segment (PAC)" ;
    rdfs:comment "A PAC segment specifying packaging details." ;
    rdfs:subClassOf :Segment .

:TransportSegment a owl:Class ;
    rdfs:label "Transport Segment (TOD)" ;
    rdfs:comment "A TOD segment specifying transport arrangements." ;
    rdfs:subClassOf :Segment .

#################################################################
# REIFICATION/PIVOT CLASSES
#################################################################

:OrganizationRoleAssignment a owl:Class ;
    rdfs:label "Organization Role Assignment" ;
    rdfs:comment "Pivot class for relating an organization to a role in a specific invoice context." .

:InvoiceItemAssignment a owl:Class ;
    rdfs:label "Invoice Item Assignment" ;
    rdfs:comment "Pivot class for relating an invoice to a specific item and its details." .

:AllowanceChargeAssignment a owl:Class ;
    rdfs:label "Allowance Charge Assignment" ;
    rdfs:comment "Pivot class for relating an invoice to an allowance or charge." .

:DeliveryAssignment a owl:Class ;
    rdfs:label "Delivery Assignment" ;
    rdfs:comment "Pivot class for relating an invoice to delivery information." .

:TaxBreakdownAssignment a owl:Class ;
    rdfs:label "Tax Breakdown Assignment" ;
    rdfs:comment "Pivot class for relating an invoice to tax breakdown details." .

#################################################################
# SECTIONS AND LINE ITEMS
#################################################################

:HeaderSection a owl:Class ;
    rdfs:label "Header Section" ;
    rdfs:comment "The header section of an invoice message." .

:DetailSection a owl:Class ;
    rdfs:label "Detail Section" ;
    rdfs:comment "The detail (line items) section of an invoice message." .

:SummarySection a owl:Class ;
    rdfs:label "Summary Section" ;
    rdfs:comment "The summary section of an invoice message." .

:LineItem a owl:Class ;
    rdfs:label "Line Item" ;
    rdfs:comment "A line item within the detail section of an invoice." ;
    rdfs:subClassOf :DetailSection .

#################################################################
# PROPERTIES (OBJECT AND DATA)
#################################################################

:containsMessage a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :InterchangeEnvelope ;
    rdfs:range :Message ;
    rdfs:label "contains message" ;
    rdfs:comment "Relates an Interchange Envelope to the contained Message." .
    owl:inverseOf :isMessageContainedIn .

:isMessageContainedIn a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :InterchangeEnvelope ;
    rdfs:label "is message contained in" ;
    rdfs:comment "Inverse of containsMessage." .

:hasSegment a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :Segment ;
    rdfs:label "has segment" ;
    rdfs:comment "Relates a Message to its constituent Segments." ;
    owl:inverseOf :isSegmentOfMessage .

:isSegmentOfMessage a owl:ObjectProperty ;
    rdfs:domain :Segment ;
    rdfs:range :Message ;
    rdfs:label "is segment of message" ;
    rdfs:comment "Inverse of hasSegment." .

:hasBeginningOfMessage a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :Message ;
    rdfs:range :BeginningOfMessage ;
    rdfs:label "has beginning of message" ;
    rdfs:comment "Links a Message to its BeginningOfMessage (BGM) segment." ;
    owl:inverseOf :isBeginningOfMessageOf .

:isBeginningOfMessageOf a owl:ObjectProperty ;
    rdfs:domain :BeginningOfMessage ;
    rdfs:range :Message ;
    rdfs:label "is beginning of message of" ;
    rdfs:comment "Inverse of hasBeginningOfMessage." .

:hasDateTimePeriod a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :DateTimePeriod ;
    rdfs:label "has date time period" ;
    rdfs:comment "Links a Message to its DTM segments." ;
    owl:inverseOf :isDateTimePeriodOfMessage .

:isDateTimePeriodOfMessage a owl:ObjectProperty ;
    rdfs:domain :DateTimePeriod ;
    rdfs:range :Message ;
    rdfs:label "is date time period of message" ;
    rdfs:comment "Inverse of hasDateTimePeriod." .

:hasReference a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :Reference ;
    rdfs:label "has reference" ;
    rdfs:comment "Links a Message to its RFF segments." ;
    owl:inverseOf :isReferenceOfMessage .

:isReferenceOfMessage a owl:ObjectProperty ;
    rdfs:domain :Reference ;
    rdfs:range :Message ;
    rdfs:label "is reference of message" ;
    rdfs:comment "Inverse of hasReference." .

:hasPriceSegment a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :PriceSegment ;
    rdfs:label "has price segment" ;
    rdfs:comment "Links a Message to its PRI segments." ;
    owl:inverseOf :isPriceSegmentOfMessage .

:isPriceSegmentOfMessage a owl:ObjectProperty ;
    rdfs:domain :PriceSegment ;
    rdfs:range :Message ;
    rdfs:label "is price segment of message" ;
    rdfs:comment "Inverse of hasPriceSegment." .

:hasQuantitySegment a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :QuantitySegment ;
    rdfs:label "has quantity segment" ;
    rdfs:comment "Links a Message to its QTY segments." ;
    owl:inverseOf :isQuantitySegmentOfMessage .

:isQuantitySegmentOfMessage a owl:ObjectProperty ;
    rdfs:domain :QuantitySegment ;
    rdfs:range :Message ;
    rdfs:label "is quantity segment of message" ;
    rdfs:comment "Inverse of hasQuantitySegment." .

:hasTaxSegment a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :TaxSegment ;
    rdfs:label "has tax segment" ;
    rdfs:comment "Links a Message to its TAX segments." ;
    owl:inverseOf :isTaxSegmentOfMessage .

:isTaxSegmentOfMessage a owl:ObjectProperty ;
    rdfs:domain :TaxSegment ;
    rdfs:range :Message ;
    rdfs:label "is tax segment of message" ;
    rdfs:comment "Inverse of hasTaxSegment." .

:hasAllowanceChargeSegment a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :AllowanceChargeSegment ;
    rdfs:label "has allowance charge segment" ;
    rdfs:comment "Links a Message to its ALC segments." ;
    owl:inverseOf :isAllowanceChargeSegmentOfMessage .

:isAllowanceChargeSegmentOfMessage a owl:ObjectProperty ;
    rdfs:domain :AllowanceChargeSegment ;
    rdfs:range :Message ;
    rdfs:label "is allowance charge segment of message" ;
    rdfs:comment "Inverse of hasAllowanceChargeSegment." .

:hasSectionControl a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :SectionControl ;
    rdfs:label "has section control" ;
    rdfs:comment "Links a Message to its UNS (Section Control) segment." ;
    owl:inverseOf :isSectionControlOfMessage .

:isSectionControlOfMessage a owl:ObjectProperty ;
    rdfs:domain :SectionControl ;
    rdfs:range :Message ;
    rdfs:label "is section control of message" ;
    rdfs:comment "Inverse of hasSectionControl." .

:identifiesInvoice a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :BeginningOfMessage ;
    rdfs:range :Invoice ;
    rdfs:label "identifies invoice" ;
    rdfs:comment "Relates the BGM segment to the Invoice it identifies." ;
    owl:inverseOf :isInvoiceIdentifiedBy .

:isInvoiceIdentifiedBy a owl:ObjectProperty ;
    rdfs:domain :Invoice ;
    rdfs:range :BeginningOfMessage ;
    rdfs:label "is invoice identified by" ;
    rdfs:comment "Inverse of identifiesInvoice." .

:involvesOrganization a owl:ObjectProperty ;
    rdfs:domain :Invoice ;
    rdfs:range :OrganizationRoleAssignment ;
    rdfs:label "involves organization" ;
    rdfs:comment "Relates an Invoice to an OrganizationRoleAssignment pivot class." ;
    owl:inverseOf :isOrganizationInvolvedIn .

:isOrganizationInvolvedIn a owl:ObjectProperty ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :Invoice ;
    rdfs:label "is organization involved in" ;
    rdfs:comment "Inverse of involvesOrganization." .

:hasRole a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :AgentRole ;
    rdfs:label "has role" ;
    rdfs:comment "Assigns a specific AgentRole to an Organization within an Invoice." ;
    owl:inverseOf :isRoleOfAssignment .

:isRoleOfAssignment a owl:ObjectProperty ;
    rdfs:domain :AgentRole ;
    rdfs:range :OrganizationRoleAssignment ;
    rdfs:label "is role of assignment" ;
    rdfs:comment "Inverse of hasRole." .

:hasOrganization a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :Organization ;
    rdfs:label "has organization" ;
    rdfs:comment "Links an OrganizationRoleAssignment to the Organization." ;
    owl:inverseOf :isOrganizationOfAssignment .

:isOrganizationOfAssignment a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :OrganizationRoleAssignment ;
    rdfs:label "is organization of assignment" ;
    rdfs:comment "Inverse of hasOrganization." .

:hasAddress a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :Address ;
    rdfs:label "has address" ;
    rdfs:comment "Links an Organization to its Address." ;
    owl:inverseOf :isAddressOfOrganization .

:isAddressOfOrganization a owl:ObjectProperty ;
    rdfs:domain :Address ;
    rdfs:range :Organization ;
    rdfs:label "is address of organization" ;
    rdfs:comment "Inverse of hasAddress." .

:hasIdentifier a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :Identifier ;
    rdfs:label "has identifier" ;
    rdfs:comment "Links an Organization to its Identifier (e.g., GLN)." ;
    owl:inverseOf :isIdentifierOfOrganization .

:isIdentifierOfOrganization a owl:ObjectProperty ;
    rdfs:domain :Identifier ;
    rdfs:range :Organization ;
    rdfs:label "is identifier of organization" ;
    rdfs:comment "Inverse of hasIdentifier." .

:hasGlobalLocationNumber a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :Organization ;
    rdfs:range :GlobalLocationNumber ;
    rdfs:label "has GLN" ;
    rdfs:comment "Links an Organization to its Global Location Number." ;
    owl:inverseOf :isGLNOfOrganization .

:isGLNOfOrganization a owl:ObjectProperty ;
    rdfs:domain :GlobalLocationNumber ;
    rdfs:range :Organization ;
    rdfs:label "is GLN of organization" ;
    rdfs:comment "Inverse of hasGlobalLocationNumber." .

:hasInvoiceItem a owl:ObjectProperty ;
    rdfs:domain :Invoice ;
    rdfs:range :InvoiceItemAssignment ;
    rdfs:label "has invoice item" ;
    rdfs:comment "Links an Invoice to its InvoiceItemAssignment pivot class." ;
    owl:inverseOf :isInvoiceItemOf .

:isInvoiceItemOf a owl:ObjectProperty ;
    rdfs:domain :InvoiceItemAssignment ;
    rdfs:range :Invoice ;
    rdfs:label "is invoice item of" ;
    rdfs:comment "Inverse of hasInvoiceItem." .

:hasItem a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :InvoiceItemAssignment ;
    rdfs:range :Item ;
    rdfs:label "has item" ;
    rdfs:comment "Assigns an Item to an InvoiceItemAssignment." ;
    owl:inverseOf :isItemOfAssignment .

:isItemOfAssignment a owl:ObjectProperty ;
    rdfs:domain :Item ;
    rdfs:range :InvoiceItemAssignment ;
    rdfs:label "is item of assignment" ;
    rdfs:comment "Inverse of hasItem." .

:hasPrice a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :InvoiceItemAssignment ;
    rdfs:range :Price ;
    rdfs:label "has price" ;
    rdfs:comment "Assigns a Price to an InvoiceItemAssignment." ;
    owl:inverseOf :isPriceOfAssignment .

:isPriceOfAssignment a owl:ObjectProperty ;
    rdfs:domain :Price ;
    rdfs:range :InvoiceItemAssignment ;
    rdfs:label "is price of assignment" ;
    rdfs:comment "Inverse of hasPrice." .

:hasQuantity a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :InvoiceItemAssignment ;
    rdfs:range :Quantity ;
    rdfs:label "has quantity" ;
    rdfs:comment "Assigns a Quantity to an InvoiceItemAssignment." ;
    owl:inverseOf :isQuantityOfAssignment .

:isQuantityOfAssignment a owl:ObjectProperty ;
    rdfs:domain :Quantity ;
    rdfs:range :InvoiceItemAssignment ;
    rdfs:label "is quantity of assignment" ;
    rdfs:comment "Inverse of hasQuantity." .

:hasTax a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :InvoiceItemAssignment ;
    rdfs:range :Tax ;
    rdfs:label "has tax" ;
    rdfs:comment "Assigns a Tax to an InvoiceItemAssignment." ;
    owl:inverseOf :isTaxOfAssignment .

:isTaxOfAssignment a owl:ObjectProperty ;
    rdfs:domain :Tax ;
    rdfs:range :InvoiceItemAssignment ;
    rdfs:label "is tax of assignment" ;
    rdfs:comment "Inverse of hasTax." .

:hasBusinessProcess a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :Invoice ;
    rdfs:range :BusinessProcess ;
    rdfs:label "has business process" ;
    rdfs:comment "Assigns a BusinessProcess to an Invoice." ;
    owl:inverseOf :isBusinessProcessOf .

:isBusinessProcessOf a owl:ObjectProperty ;
    rdfs:domain :BusinessProcess ;
    rdfs:range :Invoice ;
    rdfs:label "is business process of" ;
    rdfs:comment "Inverse of hasBusinessProcess." .

# Section and Assignment Connections (fixing P04)
:hasHeaderSection a owl:ObjectProperty ;
    rdfs:domain :Invoice ;
    rdfs:range :HeaderSection ;
    rdfs:label "has header section" ;
    rdfs:comment "Connects an Invoice to its HeaderSection." ;
    owl:inverseOf :isHeaderSectionOf .

:isHeaderSectionOf a owl:ObjectProperty ;
    rdfs:domain :HeaderSection ;
    rdfs:range :Invoice ;
    rdfs:label "is header section of" ;
    rdfs:comment "Inverse of hasHeaderSection." .

:hasDetailSection a owl:ObjectProperty ;
    rdfs:domain :Invoice ;
    rdfs:range :DetailSection ;
    rdfs:label "has detail section" ;
    rdfs:comment "Connects an Invoice to its DetailSection." ;
    owl:inverseOf :isDetailSectionOf .

:isDetailSectionOf a owl:ObjectProperty ;
    rdfs:domain :DetailSection ;
    rdfs:range :Invoice ;
    rdfs:label "is detail section of" ;
    rdfs:comment "Inverse of hasDetailSection." .

:hasSummarySection a owl:ObjectProperty ;
    rdfs:domain :Invoice ;
    rdfs:range :SummarySection ;
    rdfs:label "has summary section" ;
    rdfs:comment "Connects an Invoice to its SummarySection." ;
    owl:inverseOf :isSummarySectionOf .

:isSummarySectionOf a owl:ObjectProperty ;
    rdfs:domain :SummarySection ;
    rdfs:range :Invoice ;
    rdfs:label "is summary section of" ;
    rdfs:comment "Inverse of hasSummarySection." .

:hasDeliveryAssignment a owl:ObjectProperty ;
    rdfs:domain :Invoice ;
    rdfs:range :DeliveryAssignment ;
    rdfs:label "has delivery assignment" ;
    rdfs:comment "Connects an Invoice to its DeliveryAssignment." ;
    owl:inverseOf :isDeliveryAssignmentOf .

:isDeliveryAssignmentOf a owl:ObjectProperty ;
    rdfs:domain :DeliveryAssignment ;
    rdfs:range :Invoice ;
    rdfs:label "is delivery assignment of" ;
    rdfs:comment "Inverse of hasDeliveryAssignment." .

:hasAllowanceChargeAssignment a owl:ObjectProperty ;
    rdfs:domain :Invoice ;
    rdfs:range :AllowanceChargeAssignment ;
    rdfs:label "has allowance charge assignment" ;
    rdfs:comment "Connects an Invoice to its AllowanceChargeAssignment." ;
    owl:inverseOf :isAllowanceChargeAssignmentOf .

:isAllowanceChargeAssignmentOf a owl:ObjectProperty ;
    rdfs:domain :AllowanceChargeAssignment ;
    rdfs:range :Invoice ;
    rdfs:label "is allowance charge assignment of" ;
    rdfs:comment "Inverse of hasAllowanceChargeAssignment." .

:hasTaxBreakdownAssignment a owl:ObjectProperty ;
    rdfs:domain :Invoice ;
    rdfs:range :TaxBreakdownAssignment ;
    rdfs:label "has tax breakdown assignment" ;
    rdfs:comment "Connects an Invoice to its TaxBreakdownAssignment." ;
    owl:inverseOf :isTaxBreakdownAssignmentOf .

:isTaxBreakdownAssignmentOf a owl:ObjectProperty ;
    rdfs:domain :TaxBreakdownAssignment ;
    rdfs:range :Invoice ;
    rdfs:label "is tax breakdown assignment of" ;
    rdfs:comment "Inverse of hasTaxBreakdownAssignment." .

#################################################################
# DATA PROPERTIES
#################################################################

:invoiceAmount a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :Invoice ;
    rdfs:range xsd:decimal ;
    rdfs:label "invoice amount" ;
    rdfs:comment "The total amount of the invoice." .

:invoiceNumber a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :Invoice ;
    rdfs:range xsd:string ;
    rdfs:label "invoice number" ;
    rdfs:comment "The unique number identifying the invoice." .

:itemNetPrice a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :Price ;
    rdfs:range xsd:decimal ;
    rdfs:label "item net price" ;
    rdfs:comment "The net price of an item in the invoice." .

:itemQuantity a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :Quantity ;
    rdfs:range xsd:integer ;
    rdfs:label "item quantity" ;
    rdfs:comment "The quantity of an item in the invoice." .

:taxAmount a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :Tax ;
    rdfs:range xsd:decimal ;
    rdfs:label "tax amount" ;
    rdfs:comment "The amount of tax applied to an item or invoice." .

:addressLine a owl:DatatypeProperty ;
    rdfs:domain :Address ;
    rdfs:range xsd:string ;
    rdfs:label "address line" ;
    rdfs:comment "The street address or address line." .

:postalCode a owl:DatatypeProperty ;
    rdfs:domain :Address ;
    rdfs:range xsd:string ;
    rdfs:label "postal code" ;
    rdfs:comment "The postal code of an address." .

:city a owl:DatatypeProperty ;
    rdfs:domain :Address ;
    rdfs:range xsd:string ;
    rdfs:label "city" ;
    rdfs:comment "The city of an address." .

:country a owl:DatatypeProperty ;
    rdfs:domain :Address ;
    rdfs:range xsd:string ;
    rdfs:label "country" ;
    rdfs:comment "The country of an address." .

#################################################################
# MOA QUALIFIER-SPECIFIC CLASSES & PROPERTIES
#################################################################

:MOA79 a owl:Class ;
    rdfs:label "Invoice Line Net Amount (MOA+79)" ;
    rdfs:comment "Monetary amount for line net." ;
    rdfs:subClassOf :MonetaryAmountSegment .

:MOA86 a owl:Class ;
    rdfs:label "Line Item Amount (MOA+86)" ;
    rdfs:comment "Monetary amount for line item total." ;
    rdfs:subClassOf :MonetaryAmountSegment .

:MOA125 a owl:Class ;
    rdfs:label "Taxable Amount (MOA+125)" ;
    rdfs:comment "Taxable base amount." ;
    rdfs:subClassOf :MonetaryAmountSegment .

:MOA176 a owl:Class ;
    rdfs:label "Invoice Total Amount (MOA+176)" ;
    rdfs:comment "Total amount for the invoice." ;
    rdfs:subClassOf :MonetaryAmountSegment .

:MOA289 a owl:Class ;
    rdfs:label "Tax Base Amount (MOA+289)" ;
    rdfs:comment "Tax base amount for VAT, etc." ;
    rdfs:subClassOf :MonetaryAmountSegment .

:hasMOA79 a owl:ObjectProperty ;
    rdfs:domain :InvoiceItemAssignment ;
    rdfs:range :MOA79 ;
    rdfs:label "has MOA+79" ;
    rdfs:comment "Links a line item assignment to its MOA+79 (net amount)." ;
    owl:inverseOf :isMOA79Of .

:isMOA79Of a owl:ObjectProperty ;
    rdfs:domain :MOA79 ;
    rdfs:range :InvoiceItemAssignment ;
    rdfs:label "is MOA+79 of" ;
    rdfs:comment "Inverse of hasMOA79." .

:hasMOA86 a owl:ObjectProperty ;
    rdfs:domain :InvoiceItemAssignment ;
    rdfs:range :MOA86 ;
    rdfs:label "has MOA+86" ;
    rdfs:comment "Links a line item assignment to its MOA+86 (line item amount)." ;
    owl:inverseOf :isMOA86Of .

:isMOA86Of a owl:ObjectProperty ;
    rdfs:domain :MOA86 ;
    rdfs:range :InvoiceItemAssignment ;
    rdfs:label "is MOA+86 of" ;
    rdfs:comment "Inverse of hasMOA86." .

:hasMOA125 a owl:ObjectProperty ;
    rdfs:domain :Invoice ;
    rdfs:range :MOA125 ;
    rdfs:label "has MOA+125" ;
    rdfs:comment "Links an invoice to its MOA+125 (taxable amount)." ;
    owl:inverseOf :isMOA125Of .

:isMOA125Of a owl:ObjectProperty ;
    rdfs:domain :MOA125 ;
    rdfs:range :Invoice ;
    rdfs:label "is MOA+125 of" ;
    rdfs:comment "Inverse of hasMOA125." .

:hasMOA176 a owl:ObjectProperty ;
    rdfs:domain :Invoice ;
    rdfs:range :MOA176 ;
    rdfs:label "has MOA+176" ;
    rdfs:comment "Links an invoice to its MOA+176 (total amount)." ;
    owl:inverseOf :isMOA176Of .

:isMOA176Of a owl:ObjectProperty ;
    rdfs:domain :MOA176 ;
    rdfs:range :Invoice ;
    rdfs:label "is MOA+176 of" ;
    rdfs:comment "Inverse of hasMOA176." .

:hasMOA289 a owl:ObjectProperty ;
    rdfs:domain :Invoice ;
    rdfs:range :MOA289 ;
    rdfs:label "has MOA+289" ;
    rdfs:comment "Links an invoice to its MOA+289 (tax base amount)." ;
    owl:inverseOf :isMOA289Of .

:isMOA289Of a owl:ObjectProperty ;
    rdfs:domain :MOA289 ;
    rdfs:range :Invoice ;
    rdfs:label "is MOA+289 of" ;
    rdfs:comment "Inverse of hasMOA289." .

#################################################################
# DISJOINT CLASSES
#################################################################

:AgentRole owl:disjointWith :Organization .
:CompositeDataElement owl:disjointWith :SimpleDataElement .
:HeaderSection owl:disjointWith :DetailSection , :SummarySection .
:DetailSection owl:disjointWith :SummarySection .
"}

