@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

<http://www.example.org/ontology#EDIFACT-INVOIC-Ontology> a owl:Ontology ;
    rdfs:label "EDIFACT INVOIC Profound Ontology" ;
    rdfs:comment "A comprehensive OWL2 ontology for the structure of EDIFACT D96A INVOIC messages, supporting EN 16931-1, P2P-O alignment, and SHACL validation." .

#################################################################
# CORE CLASSES
#################################################################

:InterchangeEnvelope a owl:Class ;
    rdfs:label "Interchange Envelope" ;
    rdfs:comment "The top-level UN/EDIFACT envelope containing one or more messages." .

:Message a owl:Class ;
    rdfs:label "Message" ;
    rdfs:comment "A business message such as INVOIC within the Interchange Envelope." .

:Segment a owl:Class ;
    rdfs:label "Segment" ;
    rdfs:comment "A generic EDIFACT segment, the building block of a message." .

:CompositeDataElement a owl:Class ;
    rdfs:label "Composite Data Element" ;
    rdfs:comment "A composite data element within a segment." ;
    rdfs:subClassOf :Segment .

:SimpleDataElement a owl:Class ;
    rdfs:label "Simple Data Element" ;
    rdfs:comment "A simple data element within a composite or segment." ;
    rdfs:subClassOf :Segment .

:Invoice a owl:Class ;
    rdfs:label "Invoice" ;
    rdfs:comment "An invoice document, represented as an INVOIC message." ;
    rdfs:subClassOf :Message .

:Organization a owl:Class ;
    rdfs:label "Organization" ;
    rdfs:comment "A business entity involved in the invoice (buyer, seller, delivery party, etc.)." .

:AgentRole a owl:Class ;
    rdfs:label "Agent Role" ;
    rdfs:comment "A specific role played by an organization in the context of an invoice (e.g., Buyer, Supplier, Delivery Party)." .

:Address a owl:Class ;
    rdfs:label "Address" ;
    rdfs:comment "A postal or physical address related to an organization." .

:Identifier a owl:Class ;
    rdfs:label "Identifier" ;
    rdfs:comment "A generic identifier such as a Global Location Number." .

:GlobalLocationNumber a owl:Class ;
    rdfs:label "Global Location Number" ;
    rdfs:comment "A unique identifier for an organization location, e.g., GLN." ;
    rdfs:subClassOf :Identifier .

:Item a owl:Class ;
    rdfs:label "Item" ;
    rdfs:comment "A product or service listed in the invoice." .

:Price a owl:Class ;
    rdfs:label "Price" ;
    rdfs:comment "A price value associated with an item or invoice." .

:Quantity a owl:Class ;
    rdfs:label "Quantity" ;
    rdfs:comment "A quantity value for an item or invoice." .

:Tax a owl:Class ;
    rdfs:label "Tax" ;
    rdfs:comment "A tax concept applied to an item or invoice." .

:BusinessProcess a owl:Class ;
    rdfs:label "Business Process" ;
    rdfs:comment "A business process to which the invoice can be assigned." .

#################################################################
# SEGMENT-LEVEL AND PIVOT CLASSES
#################################################################

:BeginningOfMessage a owl:Class ;
    rdfs:label "Beginning of Message Segment (BGM)" ;
    rdfs:comment "The BGM segment, identifying the type and number of the document." ;
    rdfs:subClassOf :Segment .

:DateTimePeriod a owl:Class ;
    rdfs:label "Date/Time/Period Segment (DTM)" ;
    rdfs:comment "A DTM segment specifying a relevant date or period (e.g., invoice date, delivery date)." ;
    rdfs:subClassOf :Segment .

:Reference a owl:Class ;
    rdfs:label "Reference Segment (RFF)" ;
    rdfs:comment "A reference segment for document numbers, order references, etc." ;
    rdfs:subClassOf :Segment .

:PriceSegment a owl:Class ;
    rdfs:label "Price Segment (PRI)" ;
    rdfs:comment "A PRI segment specifying price details for line items." ;
    rdfs:subClassOf :Segment .

:QuantitySegment a owl:Class ;
    rdfs:label "Quantity Segment (QTY)" ;
    rdfs:comment "A QTY segment specifying quantity details for line items." ;
    rdfs:subClassOf :Segment .

:TaxSegment a owl:Class ;
    rdfs:label "Tax Segment (TAX)" ;
    rdfs:comment "A TAX segment specifying tax details for invoice or line items." ;
    rdfs:subClassOf :Segment .

:AllowanceChargeSegment a owl:Class ;
    rdfs:label "Allowance/Charge Segment (ALC)" ;
    rdfs:comment "An ALC segment specifying allowances or charges." ;
    rdfs:subClassOf :Segment .

:SectionControl a owl:Class ;
    rdfs:label "Section Control Segment (UNS)" ;
    rdfs:comment "A UNS segment marking section boundaries in the message." ;
    rdfs:subClassOf :Segment .

:MonetaryAmountSegment a owl:Class ;
    rdfs:label "Monetary Amount Segment (MOA)" ;
    rdfs:comment "A MOA segment with a specific qualifier (e.g. MOA+79, MOA+86, MOA+125, MOA+176, MOA+289)." ;
    rdfs:subClassOf :Segment .

:MeasurementSegment a owl:Class ;
    rdfs:label "Measurement Segment (MEA)" ;
    rdfs:comment "A MEA segment specifying measurements (e.g., weight, volume)." ;
    rdfs:subClassOf :Segment .

:PackagingSegment a owl:Class ;
    rdfs:label "Packaging Segment (PAC)" ;
    rdfs:comment "A PAC segment specifying packaging details." ;
    rdfs:subClassOf :Segment .

:TransportSegment a owl:Class ;
    rdfs:label "Transport Segment (TOD)" ;
    rdfs:comment "A TOD segment specifying transport arrangements." ;
    rdfs:subClassOf :Segment .

#################################################################
# REIFICATION/PIVOT CLASSES
#################################################################

:OrganizationRoleAssignment a owl:Class ;
    rdfs:label "Organization Role Assignment" ;
    rdfs:comment "Pivot class for relating an organization to a role in a specific invoice context." .

:InvoiceItemAssignment a owl:Class ;
    rdfs:label "Invoice Item Assignment" ;
    rdfs:comment "Pivot class for relating an invoice to a specific item and its details." .

:AllowanceChargeAssignment a owl:Class ;
    rdfs:label "Allowance Charge Assignment" ;
    rdfs:comment "Pivot class for relating an invoice to an allowance or charge." .

:DeliveryAssignment a owl:Class ;
    rdfs:label "Delivery Assignment" ;
    rdfs:comment "Pivot class for relating an invoice to delivery information." .

:TaxBreakdownAssignment a owl:Class ;
    rdfs:label "Tax Breakdown Assignment" ;
    rdfs:comment "Pivot class for relating an invoice to tax breakdown details." .

#################################################################
# SECTIONS AND LINE ITEMS
#################################################################

:HeaderSection a owl:Class ;
    rdfs:label "Header Section" ;
    rdfs:comment "The header section of an invoice message." .

:DetailSection a owl:Class ;
    rdfs:label "Detail Section" ;
    rdfs:comment "The detail (line items) section of an invoice message." .

:SummarySection a owl:Class ;
    rdfs:label "Summary Section" ;
    rdfs:comment "The summary section of an invoice message." .

:LineItem a owl:Class ;
    rdfs:label "Line Item" ;
    rdfs:comment "A line item within the detail section of an invoice." ;
    rdfs:subClassOf :DetailSection .

#################################################################
# PROPERTIES (OBJECT AND DATA)
#################################################################

:containsMessage a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :InterchangeEnvelope ;
    rdfs:range :Message ;
    rdfs:label "contains message" ;
    rdfs:comment "Relates an Interchange Envelope to the contained Message." .
    owl:inverseOf :isMessageContainedIn .

:isMessageContainedIn a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :InterchangeEnvelope ;
    rdfs:label "is message contained in" ;
    rdfs:comment "Inverse of containsMessage." .

:hasSegment a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :Segment ;
    rdfs:label "has segment" ;
    rdfs:comment "Relates a Message to its constituent Segments." ;
    owl:inverseOf :isSegmentOfMessage .

:isSegmentOfMessage a owl:ObjectProperty ;
    rdfs:domain :Segment ;
    rdfs:range :Message ;
    rdfs:label "is segment of message" ;
    rdfs:comment "Inverse of hasSegment." .

:hasBeginningOfMessage a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :Message ;
    rdfs:range :BeginningOfMessage ;
    rdfs:label "has beginning of message" ;
    rdfs:comment "Links a Message to its BeginningOfMessage (BGM) segment." ;
    owl:inverseOf :isBeginningOfMessageOf .

:isBeginningOfMessageOf a owl:ObjectProperty ;
    rdfs:domain :BeginningOfMessage ;
    rdfs:range :Message ;
    rdfs:label "is beginning of message of" ;
    rdfs:comment "Inverse of hasBeginningOfMessage." .

:hasDateTimePeriod a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :DateTimePeriod ;
