@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

<http://www.example.org/ontology#EDIFACT_INVOICE_Story1>
    a owl:Ontology ;
    rdfs:label "UN/EDIFACT Invoice Ontology" ;
    rdfs:comment "Ontology for representing UN/EDIFACT D96A EANCOM invoice messages, envelope structure, roles, and line items." .

#################################################################
# Classes
#################################################################

:InterchangeEnvelope a owl:Class ;
    rdfs:label "Interchange Envelope" ;
    rdfs:comment "The outermost envelope in an EDIFACT interchange, containing messages." .

:Message a owl:Class ;
    rdfs:label "Message" ;
    rdfs:comment "A digital business document within the interchange envelope." .

:InvoiceMessage a owl:Class ;
    rdfs:subClassOf :Message ;
    rdfs:label "Invoice Message" ;
    rdfs:comment "A message representing an invoice (INVOIC) according to D96A/EANCOM." .

:Segment a owl:Class ;
    rdfs:label "Segment" ;
    rdfs:comment "A segment is a logical group of data elements in an EDIFACT message." .

:BGMSegment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "BGM Segment" ;
    rdfs:comment "Beginning of Message segment (BGM), identifies document type and number." .

:NADSegment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "NAD Segment" ;
    rdfs:comment "Name and Address segment (NAD), provides party identification and address details." .

:CompositeDataElement a owl:Class ;
    rdfs:label "Composite Data Element" ;
    rdfs:comment "A composite data element, grouping multiple simple data elements." .

:SimpleDataElement a owl:Class ;
    rdfs:label "Simple Data Element" ;
    rdfs:comment "A simple (atomic) data element in a segment or composite." .

:MessageHeader a owl:Class ;
    rdfs:label "Message Header" ;
    rdfs:comment "Header section of an invoice message, containing dates and reference numbers." .

:MessageDetail a owl:Class ;
    rdfs:label "Message Detail" ;
    rdfs:comment "Detail section of an invoice message, listing line items." .

:MessageSummary a owl:Class ;
    rdfs:label "Message Summary" ;
    rdfs:comment "Summary section of an invoice message, providing totals and tax information." .

:LineItemGroup a owl:Class ;
    rdfs:subClassOf :MessageDetail ;
    rdfs:label "Line Item Group" ;
    rdfs:comment "A group representing a line item (LIN loop) in the invoice detail, with item, quantity, price, and monetary breakdowns." .

:Organization a owl:Class ;
    rdfs:label "Organization" ;
    rdfs:comment "A legal entity involved in the invoice (buyer, seller, delivery party, etc.)." .

:AgentRole a owl:Class ;
    rdfs:label "Agent Role" ;
    rdfs:comment "A role played by an organization in an invoice (e.g., buyer, delivery party)." .

:BuyerRole a owl:Class ;
    rdfs:subClassOf :AgentRole ;
    rdfs:label "Buyer Role" ;
    rdfs:comment "Role of buyer in an invoice." .

:DeliveryPartyRole a owl:Class ;
    rdfs:subClassOf :AgentRole ;
    rdfs:label "Delivery Party Role" ;
    rdfs:comment "Role of delivery party in an invoice." .

:OrganizationRoleAssignment a owl:Class ;
    rdfs:label "Organization Role Assignment" ;
    rdfs:comment "Pivot class for reifying the assignment of a role to an organization in a given invoice context." .

:Address a owl:Class ;
    rdfs:label "Address" ;
    rdfs:comment "A postal or physical address associated with an organization." .

:HeadquartersAddress a owl:Class ;
    rdfs:subClassOf :Address ;
    rdfs:label "Headquarters Address" ;
    rdfs:comment "Headquarters address of an organization." .

:WarehouseAddress a owl:Class ;
    rdfs:subClassOf :Address ;
    rdfs:label "Warehouse Address" ;
    rdfs:comment "Warehouse address of an organization." .

:GlobalLocationNumber a owl:Class ;
    rdfs:label "Global Location Number" ;
    rdfs:comment "A global identifier for locations (GLN)." .

:Item a owl:Class ;
    rdfs:label "Item" ;
    rdfs:comment "A product or service listed in the invoice." .

:Price a owl:Class ;
    rdfs:label "Price" ;
    rdfs:comment "A monetary value associated with an item." .

:NetPrice a owl:Class ;
    rdfs:subClassOf :Price ;
    rdfs:label "Net Price" ;
    rdfs:comment "The net price of an item (excluding tax)." .

:InvoiceAmount a owl:Class ;
    rdfs:label "Invoice Amount" ;
    rdfs:comment "The total amount of the invoice." .

:InvoiceNumber a owl:Class ;
    rdfs:label "Invoice Number" ;
    rdfs:comment "The unique identifier for the invoice." .

:ReferenceNumber a owl:Class ;
    rdfs:label "Reference Number" ;
    rdfs:comment "A reference number in the message header." .

:Date a owl:Class ;
    rdfs:label "Date" ;
    rdfs:comment "A date value, e.g., for invoice date, delivery date." .

:TaxTotal a owl:Class ;
    rdfs:label "Tax Total" ;
    rdfs:comment "The total tax amount for the invoice." .

:BusinessProcess a owl:Class ;
    rdfs:label "Business Process" ;
