    owl:inverseOf :isItemOfLineGroup .

:isItemOfLineGroup a owl:ObjectProperty ;
    rdfs:domain :Item ;
    rdfs:range :LineItemGroup ;
    rdfs:label "is item of line group" ;
    rdfs:comment "Inverse of hasItem." .

:hasNetPrice a owl:ObjectProperty, owl:FunctionalProperty ;
