    rdfs:range :ReferenceNumber ;
    rdfs:label "has reference number" ;
    rdfs:comment "Relates the header to a reference number." ;
    owl:inverseOf :isReferenceNumberOfHeader .

:isReferenceNumberOfHeader a owl:ObjectProperty ;
    rdfs:domain :ReferenceNumber ;
    rdfs:range :MessageHeader ;
    rdfs:label "is reference number of header" ;
    rdfs:comment "Inverse of hasReferenceNumber." .

