:validatesInvoiceMessage a owl:ObjectProperty ;
    rdfs:domain :ValidationConstraint ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "validates invoice message" ;
    rdfs:comment "Inverse of isValidAccordingTo." .

#################################################################
# Data Properties (now class-specific)
#################################################################

:hasNetPriceValue a owl:DatatypeProperty ;
    rdfs:domain :NetPrice ;
    rdfs:range xsd:decimal ;
    rdfs:label "has net price value" ;
    rdfs:comment "The value of a net price." .

:hasInvoiceAmountValue a owl:DatatypeProperty ;
    rdfs:domain :InvoiceAmount ;
    rdfs:range xsd:decimal ;
    rdfs:label "has invoice amount value" ;
    rdfs:comment "The value of an invoice amount." .

:hasTaxTotalValue a owl:DatatypeProperty ;
    rdfs:domain :TaxTotal ;
    rdfs:range xsd:decimal ;
    rdfs:label "has tax total value" ;
    rdfs:comment "The value of the tax total." .

:hasInvoiceNumberValue a owl:DatatypeProperty ;
    rdfs:domain :InvoiceNumber ;
    rdfs:range xsd:string ;
    rdfs:label "has invoice number value" ;
    rdfs:comment "The value of the invoice number." .

:hasReferenceNumberValue a owl:DatatypeProperty ;
    rdfs:domain :ReferenceNumber ;
    rdfs:range xsd:string ;
    rdfs:label "has reference number value" ;
    rdfs:comment "The value of the reference number." .

:hasDateValue a owl:DatatypeProperty ;
    rdfs:domain :Date ;
    rdfs:range xsd:string ;
    rdfs:label "has date value" ;
    rdfs:comment "The value of the date as a string." .

:hasGLNValue a owl:DatatypeProperty ;
    rdfs:domain :GlobalLocationNumber ;
    rdfs:range xsd:string ;
    rdfs:label "has GLN value" ;
    rdfs:comment "The value of the global location number." .

:hasAddressValue a owl:DatatypeProperty ;
    rdfs:domain :Address ;
    rdfs:range xsd:string ;
    rdfs:label "has address value" ;
    rdfs:comment "The value of the address as a string." .

:hasQuantity a owl:DatatypeProperty ;
    rdfs:domain :Item ;
    rdfs:range xsd:decimal ;
    rdfs:label "has quantity" ;
    rdfs:comment "Specifies the quantity of an item." .

#################################################################
# Restrictions and Axioms
#################################################################

:InvoiceMessage owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf (
        :Message
        [ a owl:Restriction ; owl:onProperty :hasHeader ; owl:someValuesFrom :MessageHeader ]
        [ a owl:Restriction ; owl:onProperty :hasDetail ; owl:someValuesFrom :MessageDetail ]
        [ a owl:Restriction ; owl:onProperty :hasSummary ; owl:someValuesFrom :MessageSummary ]
    )
] .

:OrganizationRoleAssignment owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf (
        [ a owl:Restriction ; owl:onProperty :involvesOrganization ; owl:someValuesFrom :Organization ]
        [ a owl:Restriction ; owl:onProperty :hasRole ; owl:someValuesFrom :AgentRole ]
    )
] .

:LineItemGroup owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf (
        :MessageDetail
        [ a owl:Restriction ; owl:onProperty :hasItem ; owl:someValuesFrom :Item ]
    )
] .

:BuyerRole owl:disjointWith :DeliveryPartyRole .
:HeadquartersAddress owl:disjointWith :WarehouseAddress .
:MessageHeader owl:disjointWith :MessageDetail, :MessageSummary .
:MessageDetail owl:disjointWith :MessageSummary .

:MessageSection a owl:Class ;
    owl:disjointUnionOf (:MessageHeader :MessageDetail :MessageSummary) ;
    rdfs:label "Message Section" ;
    rdfs:comment "Union of header, detail, and summary sections in an invoice message." .
"}

