    rdfs:range :InvoiceAmount ;
    rdfs:label "has invoice amount" ;
    rdfs:comment "Relates the summary to the invoice amount." ;
    owl:inverseOf :isInvoiceAmountOfSummary .

:isInvoiceAmountOfSummary a owl:ObjectProperty ;
    rdfs:domain :InvoiceAmount ;
    rdfs:range :MessageSummary ;
    rdfs:label "is invoice amount of summary" ;
    rdfs:comment "Inverse of hasInvoiceAmount." .

:hasInvoiceNumber a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :InvoiceNumber ;
    rdfs:label "has invoice number" ;
    rdfs:comment "Relates an invoice message to its invoice number." ;
    owl:inverseOf :isInvoiceNumberOfMessage .

:isInvoiceNumberOfMessage a owl:ObjectProperty ;
    rdfs:domain :InvoiceNumber ;
